def check_machine_coverage(session, machine_id: str) -> dict[str, Any]:
    uses = list(session.execute(_USE_TABLE.select().where(_USE_TABLE.c.machine_id == machine_id)))
    receipts = list(session.execute(_TABLE.select().where(_TABLE.c.machine_id == machine_id)))

    receipt_use_ids = set()
    for row in receipts:
        use_id = row._mapping["use_id"]
        if isinstance(use_id, str):
            receipt_use_ids.add(use_id)

    missing = []
    covered = 0
    for row in uses:
        mapping = row._mapping
        if mapping["id"] in receipt_use_ids:
            covered += 1
        else:
            missing.append(mapping)

    use_ids = {row._mapping["id"] for row in uses}
    orphans = [row._mapping for row in receipts if row._mapping["use_id"] not in use_ids]

    missing_sorted = sorted(missing, key=lambda m: (occurred_at_instant(m["consumed_at"]), _receipt_id_key(m["id"])))
    orphan_sorted = sorted(orphans, key=lambda m: (occurred_at_instant(m["occurred_at"]), _receipt_id_key(m["id"])))

    missing_use_ids = [m["id"] for m in missing_sorted]
    orphan_receipt_ids = [m["id"] for m in orphan_sorted]

    return {
        "consumed_count": len(uses),
        "receipt_count": len(receipts),
        "covered_count": covered,
        "missing_count": len(missing),
        "missing_use_ids": missing_use_ids,
        "orphan_count": len(orphans),
        "orphan_receipt_ids": orphan_receipt_ids,
        "valid": len(missing) == 0 and len(orphans) == 0,
    }
```

